<?php if(!$chartRows): ?><div class="empty-state"><i class="bi bi-bar-chart" aria-hidden="true"></i><p>Seçilen dönemde henüz randevu yok.</p></div><?php else: ?><div class="chart-scroll"><svg class="appointment-chart" viewBox="0 0 <?= max(400,count($chartRows)*55) ?> 200" role="img" aria-label="Randevu sayıları: <?= e(implode(', ',array_map(static fn($r)=>$r[$chartKey].': '.$r['total'],$chartRows))) ?>"><title>Gerçek randevu sayıları</title><?php $maximum=max(1,max(array_column($chartRows,'total'))); foreach($chartRows as $index=>$row): $height=130*(int)$row['total']/$maximum; $x=15+$index*55; ?><rect x="<?= $x ?>" y="<?= 160-$height ?>" width="30" height="<?= $height ?>" rx="5"/><text x="<?= $x+15 ?>" y="<?= 150-$height ?>" text-anchor="middle"><?= (int)$row['total'] ?></text><text x="<?= $x+15 ?>" y="185" text-anchor="middle"><?= e(substr($row[$chartKey],5)) ?></text><?php endforeach ?></svg></div><?php endif ?>
